				out.WriteString(boxType)
				out.WriteString(" = { let mut __f_guard = ")
				out.WriteString(varName)
				WriteBorrowMethod(out, true)
				out.WriteString("; __f_guard.as_mut().unwrap() as *mut ")
				out.WriteString(boxType)
				out.WriteString(" }; let __f = unsafe { &mut *__f_ptr }; (*__f)")
